224	    if (!token) {
225	      throw new Error('No Sprites API token found. Add it in Auth first.');
226	    }
227	
228	    close();
229	    currentSpriteName = spriteName;
230	    currentSessionId = attachSessionId || undefined;
231	    options.onSessionId(currentSessionId);
232	    const stdoutDecoder = new TextDecoder();
233	    const stderrDecoder = new TextDecoder();
234	    const rawDecoder = new TextDecoder();
235	
236	    const encodedSprite = encodeURIComponent(spriteName);
237	    const isWeb = Platform.OS === 'web';
238	    const wsUrl = attachSessionId
239	      ? `${EXEC_WS_BASE}/sprites/${encodedSprite}/exec/${encodeURIComponent(attachSessionId)}${isWeb ? `?token=${encodeURIComponent(token)}` : ''}`
240	      : `${EXEC_WS_BASE}/sprites/${encodedSprite}/exec?cmd=${encodeURIComponent(command)}&tty=true&stdin=true&cols=${DEFAULT_COLS}&rows=${DEFAULT_ROWS}${isWeb ? `&token=${encodeURIComponent(token)}` : ''}`;
241	
242	    setState('connecting');
243	    tinfo('exec.conn', 'connecting', { sprite: spriteName, attach: attachSessionId, cols: DEFAULT_COLS, rows: DEFAULT_ROWS });
244	    options.onLog(makeLog('local', `Connecting: ${wsUrl}`));
245	
246	    if (isWeb) {
247	      socket = new WebSocket(wsUrl);
248	    } else {
249	      const RNWebSocket = WebSocket as unknown as RNWebSocketCtor;
250	      socket = new RNWebSocket(wsUrl, undefined, {
251	        headers: {
252	          Authorization: `Bearer ${token}`,
253	        },
254	      });
255	    }
256	    socket.binaryType = 'arraybuffer';
257	
258	    socket.onopen = () => {
259	      setState('open');
260	      tinfo('exec.conn', 'open');
261	      options.onLog(makeLog('local', 'WebSocket connected'));
262	      sendResize();
263	      if (attachSessionId) {
264	        options.onSessionId(attachSessionId);
265	      }
266	      if (initialInput) {
267	        // Give the shell a moment to print its prompt before typing into it.
268	        setTimeout(() => {
269	          if (socket && socket.readyState === WebSocket.OPEN) {
270	            socket.send(toArrayBuffer(initialInput));
271	            options.onLog(makeLog('local', 'Sent initial command'));
272	          }
273	        }, 700);
274	      }
275	    };
276	
277	    const handleBinaryFrame = (bytes: Uint8Array): boolean => {
278	      if (bytes.length === 0) return true;
279	      const streamId = bytes[0];
280	      const payload = bytes.slice(1);
281	
282	      if (streamId === 1) {
283	        const output = stdoutDecoder.decode(payload, { stream: true });
284	        if (output) options.onLog(makeLog('ws', output));
285	        return true;
286	      }
287	
288	      if (streamId === 2) {
289	        const output = stderrDecoder.decode(payload, { stream: true });
290	        if (output) options.onLog(makeLog('ws', output));
291	        return true;
292	      }
293	
294	      if (streamId === 3) {
295	        const stdoutRemainder = stdoutDecoder.decode();
296	        const stderrRemainder = stderrDecoder.decode();
297	        const rawRemainder = rawDecoder.decode();
298	        if (stdoutRemainder) options.onLog(makeLog('ws', stdoutRemainder));
299	        if (stderrRemainder) options.onLog(makeLog('ws', stderrRemainder));
300	        if (rawRemainder) options.onLog(makeLog('ws', rawRemainder));
301	        options.onLog(makeLog('local', `Exec exited with code ${parseExitCode(payload)}`));
302	        socket?.close();
303	        return true;
304	      }
305	
306	      return false;
307	    };
308	
309	    const handleTextMessage = (raw: string) => {
310	      if (stringLooksLikeBinaryFrame(raw) && handleBinaryFrame(stringToBytes(raw))) {
311	        return;
312	      }
313	
314	      let parsed: unknown;
315	      try {
316	        parsed = JSON.parse(raw);
317	      } catch {
318	        parsed = undefined;
319	      }
320	
321	      if (parsed !== undefined) {
322	        const obj = parsed as Record<string, unknown>;
323	        const eventType = asString(obj.type);
324	
325	        const sessionId = extractSessionId(parsed);
326	        if (sessionId && sessionId !== currentSessionId) {
327	          currentSessionId = sessionId;
328	          options.onSessionId(sessionId);
329	          options.onLog(makeLog('local', `Session ID: ${sessionId}`));
330	        }
331	
332	        if (eventType === 'session_info') {
333	          const cols = asNumber(obj.cols) ?? 0;
334	          const rows = asNumber(obj.rows) ?? 0;
335	          if (cols <= 0 || rows <= 0) {
336	            sendResize();
337	          }
338	          // Send init commands once the session is established
339	          if (!attachSessionId && initCommands?.length) {
340	            setTimeout(() => {
341	              for (const cmd of initCommands) {
342	                send(cmd, true);
343	              }
344	            }, 200);
345	          }
346	        }
347	
348	        if (eventType === 'exit') {
349	          const exitCode =
350	            asNumber(obj.exit_code) ??
351	            asNumber(obj.exitCode) ??
352	            0;
353	          const stdoutRemainder = stdoutDecoder.decode();
354	          const stderrRemainder = stderrDecoder.decode();
355	          const rawRemainder = rawDecoder.decode();
356	          if (stdoutRemainder) options.onLog(makeLog('ws', stdoutRemainder));
357	          if (stderrRemainder) options.onLog(makeLog('ws', stderrRemainder));
358	          if (rawRemainder) options.onLog(makeLog('ws', rawRemainder));
359	          options.onLog(makeLog('local', `Exec exited with code ${exitCode}`));
360	        }
361	
362	        const output = extractOutput(parsed);
363	        if (output) {
364	          options.onLog(makeLog('ws', output));
365	          return;
366	        }
367	
368	        options.onLog(makeLog('event', safeStringify(parsed)));
369	        return;
370	      }
371	
372	      options.onLog(makeLog('ws', raw));
373	    };
374	
375	    socket.onmessage = async (event) => {
376	      try {
377	        if (typeof event.data !== 'string') {
378	          const bytes = await messageDataToBytes(event.data);
379	          if (bytes) {
380	            tdebug('exec.msg', 'recv.bytes', {
381	              len: bytes.byteLength,
382	              first: bytes[0],
383	            });
384	            if (handleBinaryFrame(bytes)) return;
385	
386	            const raw = rawDecoder.decode(bytes, { stream: true });
387	            tdebug('exec.msg', 'recv.raw-bytes', {
388	              len: raw.length,
389	              preview: hexPreview(raw, 80),
390	            });
391	            handleTextMessage(raw);
392	            return;
393	          }
394	        }
395	
396	        const raw = await decodeMessageData(event.data);
397	        tdebug('exec.msg', 'recv', {
398	          len: raw.length,
399	          kind: typeof event.data,
400	          preview: hexPreview(raw, 80),
401	        });
402	        handleTextMessage(raw);
403	      } catch (e) {
404	        terror('exec.msg', 'message handler threw', { err: errInfo(e), kind: typeof event.data });
405	      }
406	    };
407	
408	    socket.onerror = (event) => {
409	      setState('error');
410	      twarn('exec.conn', 'error', { event: safeStringify(event) });
411	      options.onLog(makeLog('error', `WebSocket error: ${safeStringify(event)}`));
412	    };
413	
414	    socket.onclose = (event) => {
415	      const stdoutRemainder = stdoutDecoder.decode();
416	      const stderrRemainder = stderrDecoder.decode();
417	      const rawRemainder = rawDecoder.decode();
418	      if (stdoutRemainder) options.onLog(makeLog('ws', stdoutRemainder));
419	      if (stderrRemainder) options.onLog(makeLog('ws', stderrRemainder));
420	      if (rawRemainder) options.onLog(makeLog('ws', rawRemainder));
421	      setState('closed');
422	      tinfo('exec.conn', 'close', { code: event.code, reason: event.reason || 'n/a' });
423	      options.onLog(
424	        makeLog('local', `WebSocket closed (code=${event.code}, reason=${event.reason || 'n/a'})`)
425	      );
426	      socket = null;
427	    };
428	  };
429	
430	  const send = (text: string, appendNewline: boolean = true) => {
431	    if (!socket || socket.readyState !== WebSocket.OPEN) {
432	      twarn('exec.send', 'socket not open', { state: socket?.readyState });
433	      options.onLog(makeLog('error', 'Cannot send: socket is not open'));
434	      return;
435	    }
436	
437	    const payload = appendNewline ? `${text}\r` : text;
438	    tdebug('exec.send', 'send', { payload: hexPreview(payload, 60), len: payload.length });
439	    socket.send(toArrayBuffer(payload));
440	  };
441	
442	  const sendCtrlC = () => {
443	    send('\u0003', false);
444	  };
445	
446	  const kill = async () => {
447	    if (!currentSpriteName) {
448	      throw new Error('No active sprite selected for kill request.');
449	    }
450	    if (!currentSessionId) {
451	      throw new Error('No exec session ID available yet.');
452	    }
453	
454	    const token = await loadToken('spritesToken');
455	    if (!token) {
456	      throw new Error('No Sprites API token found. Add it in Auth first.');
457	    }
458	
459	    const response = await fetch(
460	      `${EXEC_HTTP_BASE}/sprites/${encodeURIComponent(currentSpriteName)}/exec/${encodeURIComponent(currentSessionId)}/kill`,
461	      {
462	        method: 'POST',
463	        headers: {
464	          Authorization: `Bearer ${token}`,
465	        },
466	      }
467	    );
468	
469	    if (!response.ok) {
470	      const body = await response.text().catch(() => '');
471	      throw new Error(body || `Kill failed (${response.status})`);
472	    }
473	
474	    options.onLog(makeLog('local', `Kill signal sent to session ${currentSessionId}`));
475	  };
476	
477	  return {
478	    connect,
479	    send,
480	    sendCtrlC,
481	    close,
482	    kill,
483	    resize: sendResize,
484	    getState: () => state,
485	    getSessionId: () => currentSessionId,
486	  };
487	}
488

