352	    throw new AppError('serverError', `Logs error ${response.status}`, response.status);
353	  }
354	
355	  const reader = response.body?.getReader();
356	  const decoder = new TextDecoder();
357	  let buffer = '';
358	  const consumeChunk = (chunk: string) => {
359	    buffer += chunk;
360	    const lines = buffer.split('\n');
361	    buffer = lines.pop() ?? '';
362	
363	    for (const line of lines) {
364	      const event = parseServiceEventLine(line);
365	      if (event) onEvent(event);
366	    }
367	  };
368	
369	  if (reader) {
370	    while (true) {
371	      const { done, value } = await reader.read();
372	      if (done) break;
373	      consumeChunk(decoder.decode(value, { stream: true }));
374	    }
375	  } else {
376	    const text = await response.text();
377	    if (text) consumeChunk(text.endsWith('\n') ? text : `${text}\n`);
378	  }
379	
380	  if (buffer.trim()) {
381	    const event = parseServiceEventLine(buffer);
382	    if (event) onEvent(event);
383	  }
384	}
