404	function makeExecWsUrl(
405	  spriteName: string,
406	  command: string[],
407	  token: string,
408	  options: StreamExecOptions
409	): string {
410	  if (options.attachSessionId) {
411	    const params = new URLSearchParams();
412	    if (Platform.OS === 'web') params.set('token', token);
413	    const query = params.toString();
414	    return `${WS_BASE_URL}/sprites/${encodeURIComponent(spriteName)}/exec/${encodeURIComponent(options.attachSessionId)}${query ? `?${query}` : ''}`;
415	  }
416	
417	  const params = new URLSearchParams();
418	  for (const part of command) params.append('cmd', part);
419	  params.set('path', options.path ?? command[0] ?? 'bash');
420	  params.set('tty', options.tty ? 'true' : 'false');
421	  params.set('stdin', options.stdin ? 'true' : 'false');
422	  params.set('max_run_after_disconnect', options.maxRunAfterDisconnect ?? '0s');
423	  if (Platform.OS === 'web') params.set('token', token);
