428	async function messageDataToBytes(data: unknown): Promise<Uint8Array | undefined> {
429	  if (data instanceof ArrayBuffer) return new Uint8Array(data);
430	  if (ArrayBuffer.isView(data)) {
431	    return new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
432	  }
433	  if (typeof Blob !== 'undefined' && data instanceof Blob) {
434	    return new Uint8Array(await data.arrayBuffer());
435	  }
436	  return undefined;
437	}
438	
439	async function messageDataToText(data: unknown): Promise<string> {
440	  if (typeof data === 'string') return data;
441	  const bytes = await messageDataToBytes(data);
442	  if (bytes) return new TextDecoder().decode(bytes);
443	  return String(data ?? '');
444	}
445	
446	function extractExecSessionId(payload: unknown): string | undefined {
447	  if (!payload || typeof payload !== 'object') return undefined;
448	  const obj = payload as Record<string, unknown>;
449	  const direct = obj.session_id ?? obj.sessionId;
450	  if (typeof direct === 'string') return direct;
451	  if (typeof direct === 'number') return String(direct);
452	  return undefined;
453	}
