455	function parseExecExitCode(bytes: Uint8Array): number {
456	  if (bytes.length === 0) return 0;
457	  if (bytes.length === 1) return bytes[0];
458	
459	  const text = new TextDecoder().decode(bytes).trim();
460	  const parsed = Number(text);
461	  return Number.isFinite(parsed) ? parsed : bytes[0];
462	}
463	
464	function stringLooksLikeBinaryFrame(text: string): boolean {
465	  if (!text) return false;
466	  const streamId = text.charCodeAt(0);
467	  return streamId >= 0 && streamId <= 4;
468	}
469	
470	function stringToBytes(text: string): Uint8Array {
471	  return Uint8Array.from(Array.from(text, (ch) => ch.charCodeAt(0) & 0xff));
472	}
