474	/**
475	 * Stream a one-shot command through the Exec API.
476	 *
477	 * Chat turns must not use the Services API: services are persistent supervised
478	 * processes and may be restarted by the sprite service manager, replaying the
479	 * same prompt into `claude --resume`. Exec sessions do not auto-restart, and
480	 * `max_run_after_disconnect` explicitly controls disconnect behavior.
481	 */
482	export async function streamExec(
483	  spriteName: string,
484	  command: string[],
485	  onEvent: (event: ServiceLogEvent) => void,
486	  signal?: AbortSignal,
487	  options: StreamExecOptions = {}
488	): Promise<void> {
489	  const token = await getToken();
490	  const url = makeExecWsUrl(spriteName, command, token, options);
491	  const stdoutDecoder = new TextDecoder();
492	  const stderrDecoder = new TextDecoder();
493	
494	  return new Promise((resolve, reject) => {
495	    if (signal?.aborted) {
496	      reject(createAbortError());
497	      return;
498	    }
499	
500	    let socket: WebSocket | null = null;
501	    let settled = false;
502	    let sawExit = false;
503	
504	    const cleanup = () => {
505	      signal?.removeEventListener('abort', handleAbort);
506	      if (socket) {
507	        socket.onopen = null;
508	        socket.onmessage = null;
509	        socket.onerror = null;
510	        socket.onclose = null;
511	      }
512	    };
513	
514	    const settle = (err?: Error) => {
515	      if (settled) return;
516	      settled = true;
517	      cleanup();
518	      if (err) {
519	        reject(err);
520	      } else {
521	        onEvent({ type: 'complete' });
522	        resolve();
523	      }
524	    };
525	
526	    const closeSocket = () => {
527	      if (!socket) return;
528	      if (socket.readyState === WebSocket.CLOSED || socket.readyState === WebSocket.CLOSING) return;
529	      socket.close();
530	    };
531	
532	    function handleAbort() {
533	      closeSocket();
534	      settle(createAbortError());
535	    }
536	
537	    const handleJsonMessage = (payload: unknown): boolean => {
538	      if (!payload || typeof payload !== 'object') return false;
539	      const obj = payload as Record<string, unknown>;
540	      const sessionId = extractExecSessionId(obj);
541	      if (sessionId) options.onSessionId?.(sessionId);
542	
543	      if (obj.type === 'session_info') {
544	        onEvent({ type: 'started' });
545	        return true;
546	      }
547	
548	      if (obj.type === 'exit') {
549	        sawExit = true;
550	        const exitCode =
551	          typeof obj.exit_code === 'number' ? obj.exit_code :
552	          typeof obj.exitCode === 'number' ? obj.exitCode :
553	          0;
554	        onEvent({ type: 'exit', exit_code: exitCode });
555	        closeSocket();
556	        return true;
557	      }
558	
559	      return false;
560	    };
561	
562	    const handleTextMessage = (text: string): boolean => {
563	      try {
564	        return handleJsonMessage(JSON.parse(text));
565	      } catch {
566	        return false;
567	      }
568	    };
569	
570	    const handleBinaryMessage = (bytes: Uint8Array) => {
571	      if (bytes.length === 0) return;
572	      const streamId = bytes[0];
573	      const payload = bytes.slice(1);
574	
575	      if (streamId === 1) {
576	        const data = stdoutDecoder.decode(payload, { stream: true });
577	        if (data) onEvent({ type: 'stdout', data });
578	      } else if (streamId === 2) {
579	        const data = stderrDecoder.decode(payload, { stream: true });
580	        if (data) onEvent({ type: 'stderr', data });
581	      } else if (streamId === 3) {
582	        const stdoutRemainder = stdoutDecoder.decode();
583	        const stderrRemainder = stderrDecoder.decode();
584	        if (stdoutRemainder) onEvent({ type: 'stdout', data: stdoutRemainder });
585	        if (stderrRemainder) onEvent({ type: 'stderr', data: stderrRemainder });
586	        sawExit = true;
587	        onEvent({ type: 'exit', exit_code: parseExecExitCode(payload) });
588	        closeSocket();
589	      }
590	    };
591	
592	    signal?.addEventListener('abort', handleAbort, { once: true });
593	
594	    if (Platform.OS === 'web') {
595	      socket = new WebSocket(url);
596	    } else {
597	      const RNWebSocket = WebSocket as unknown as RNWebSocketCtor;
598	      socket = new RNWebSocket(url, undefined, {
599	        headers: {
600	          Authorization: `Bearer ${token}`,
601	        },
602	      });
603	    }
604	
605	    socket.binaryType = 'arraybuffer';
606	
607	    socket.onopen = () => {
608	      onEvent({ type: 'started' });
609	    };
610	
611	    socket.onmessage = async (event) => {
612	      try {
613	        if (typeof event.data === 'string') {
614	          if (stringLooksLikeBinaryFrame(event.data)) {
615	            handleBinaryMessage(stringToBytes(event.data));
616	            return;
617	          }
618	          if (!handleTextMessage(event.data)) {
619	            onEvent({ type: 'stdout', data: event.data });
620	          }
621	          return;
622	        }
623	
624	        const bytes = await messageDataToBytes(event.data);
625	        if (bytes) {
626	          handleBinaryMessage(bytes);
627	          return;
628	        }
629	
630	        const text = await messageDataToText(event.data);
631	        if (!handleTextMessage(text)) {
632	          onEvent({ type: 'stdout', data: text });
633	        }
634	      } catch (err) {
635	        settle(err as Error);
636	      }
637	    };
638	
639	    socket.onerror = () => {
640	      closeSocket();
641	      settle(new AppError('networkError', 'Exec WebSocket error'));
642	    };
643	
644	    socket.onclose = () => {
645	      if (signal?.aborted) {
646	        settle(createAbortError());
647	        return;
648	      }
649	      if (!sawExit) {
650	        if (options.onDisconnectBeforeExit) {
651	          options.onDisconnectBeforeExit();
652	        } else {
653	          onEvent({ type: 'exit', exit_code: 0 });
654	        }
655	      }
656	      settle();
657	    };
658	  });
659	}
