661	/**
662	 * Start a long-running service and let it keep running in the background.
663	 * `streamService` only resolves when the service exits, so this fires it without
664	 * awaiting and resolves `started` once the first lifecycle event arrives (or after
665	 * `settleMs`). Aborting the returned controller stops *streaming logs*; use
666	 * `deleteService` to actually stop the service.
667	 */
668	export function startBackgroundService(
669	  spriteName: string,
670	  serviceName: string,
671	  config: ServiceRequest,
672	  onEvent?: (event: ServiceLogEvent) => void,
673	  settleMs: number = 1500
674	): { controller: AbortController; started: Promise<void> } {
675	  const controller = new AbortController();
676	  const started = new Promise<void>((resolve) => {
677	    let settled = false;
678	    const settle = () => {
679	      if (settled) return;
680	      settled = true;
681	      resolve();
682	    };
683	    const timer = setTimeout(settle, settleMs);
684	    streamService(
685	      spriteName,
686	      serviceName,
687	      config,
688	      (event) => {
689	        onEvent?.(event);
690	        if (event.type === 'started' || event.type === 'stdout' || event.type === 'stderr') {
691	          settle();
692	        }
693	      },
694	      controller.signal
695	    )
696	      .catch((err) => {
697	        if ((err as Error)?.name !== 'AbortError') {
698	          onEvent?.({ type: 'error', data: (err as Error).message });
699	        }
700	      })
701	      .finally(() => {
702	        clearTimeout(timer);
703	        settle();
704	      });
705	  });
706	  return { controller, started };
707	}
