800	/**
801	 * Run a short command on a sprite via the Exec API.
802	 * Creates a temporary exec session and collects stdout.
803	 * Used for simple operations like waking sprites or fetching session info.
804	 */
805	export async function runExec(
806	  spriteName: string,
807	  command: string,
808	  timeout: number = 15
809	): Promise<{ output: string; success: boolean }> {
810	  let output = '';
811	  let exitCode: number | undefined;
812	  const controller = new AbortController();
813	  const timer = setTimeout(() => controller.abort(), timeout * 1000);
814	
815	  try {
816	    await streamExec(
817	      spriteName,
818	      ['bash', '-c', command],
819	      (event) => {
820	        if (event.type === 'stdout' && event.data) {
821	          output += event.data;
822	        } else if (event.type === 'exit') {
823	          exitCode = event.exit_code ?? 0;
824	        }
825	      },
826	      controller.signal,
827	      {
828	        path: '/bin/bash',
829	        maxRunAfterDisconnect: '1s',
830	      }
831	    );
832	  } catch (err: any) {
833	    if (err.name !== 'AbortError') {
834	      exitCode = exitCode ?? 1;
835	    }
836	  } finally {
837	    clearTimeout(timer);
838	  }
839	
840	  return { output, success: exitCode === 0 };
