715	          <Text style={[styles.statusText, { color: colors.tint }]}>Open</Text>
716	        </Pressable>
717	      </View>
718	
719	      {/* Preferences Section */}
720	      <Text style={[styles.sectionHeader, { color: colors.textSecondary }]}>PREFERENCES</Text>
721	      <View style={[styles.sectionCard, { backgroundColor: colors.card }]}>
