2	import {
3	  View,
4	  Text,
5	  TextInput,
6	  StyleSheet,
7	  Pressable,
8	  ActivityIndicator,
9	  KeyboardAvoidingView,
10	  Platform,
11	} from 'react-native';
12	import { useTheme } from '@/hooks/use-theme';
13	import { FontSize, Spacing } from '@/constants/theme';
14	
15	interface CreateSpriteSheetProps {
16	  onClose: () => void;
17	  onCreate: (name: string) => Promise<void>;
18	}
19	
20	export function CreateSpriteSheet({ onClose, onCreate }: CreateSpriteSheetProps) {
21	  const colors = useTheme();
22	  const [name, setName] = useState('');
23	  const [isCreating, setIsCreating] = useState(false);
24	  const [error, setError] = useState<string>();
25	
26	  const handleCreate = async () => {
27	    const trimmed = name.trim().toLowerCase().replace(/[^a-z0-9-]/g, '-');
28	    if (!trimmed) {
29	      setError('Please enter a name');
30	      return;
31	    }
32	    setIsCreating(true);
33	    setError(undefined);
34	    try {
35	      await onCreate(trimmed);
36	      onClose();
37	    } catch (err: any) {
38	      setError(err.message ?? 'Failed to create sprite');
39	    } finally {
40	      setIsCreating(false);
41	    }
42	  };
43	
44	  return (
45	    <KeyboardAvoidingView
46	      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
47	      style={[styles.overlay, { backgroundColor: 'rgba(0,0,0,0.5)' }]}
48	    >
49	      <Pressable style={styles.backdrop} onPress={onClose} />
50	      <View style={[styles.sheet, { backgroundColor: colors.card }]}>
51	        <Text style={[styles.title, { color: colors.text }]}>New Sprite</Text>
52	        <TextInput
53	          style={[
54	            styles.input,
55	            {
56	              color: colors.text,
57	              backgroundColor: colors.inputBackground,
58	              borderColor: colors.border,
59	            },
60	          ]}
61	          placeholder="sprite-name"
62	          placeholderTextColor={colors.textSecondary}
63	          value={name}
64	          onChangeText={setName}
65	          autoCapitalize="none"
66	          autoCorrect={false}
67	          autoFocus
68	          editable={!isCreating}
69	        />
70	        {error && <Text style={[styles.error, { color: colors.destructive }]}>{error}</Text>}
71	        <View style={styles.buttons}>
72	          <Pressable
73	            style={[styles.button, { backgroundColor: colors.backgroundElement }]}
74	            onPress={onClose}
75	            disabled={isCreating}
76	          >
77	            <Text style={[styles.buttonText, { color: colors.text }]}>Cancel</Text>
78	          </Pressable>
79	          <Pressable
80	            style={[styles.button, styles.primaryButton, { backgroundColor: colors.tint }]}
81	            onPress={handleCreate}
82	            disabled={isCreating || !name.trim()}
83	          >
84	            {isCreating ? (
85	              <ActivityIndicator color="#fff" size="small" />
86	            ) : (
87	              <Text style={[styles.buttonText, { color: '#fff' }]}>Create</Text>
88	            )}
89	          </Pressable>
90	        </View>
91	      </View>
92	    </KeyboardAvoidingView>
93	  );
94	}
95	
96	const styles = StyleSheet.create({
97	  overlay: {
98	    ...StyleSheet.absoluteFillObject,
99	    justifyContent: 'flex-end',
100	  },
101	  backdrop: {
102	    flex: 1,
103	  },
104	  sheet: {
