import { readFileSync } from 'node:fs';

// ── Copied verbatim from src/services/account-auth.ts ──
const ANSI_RE = /\x1b\[[0-9;?]*[a-zA-Z]|\x1b\][0-9;]*[^\x07\x1b]*(?:\x07|\x1b\\)?|\x1b[()][0-9A-Za-z]/g;
const stripAnsi = (input) => input.replace(ANSI_RE, '');
const CODE_RE = /\b[A-Z0-9]{4}-[A-Z0-9]{4,7}\b/;
const CLAUDE_URL_RE =
  /https:\/\/claude\.com\/cai\/oauth\/authorize\?[A-Za-z0-9%._~:/?#[\]@!$&'()*+,;=-]+/g;

function parseLoginPrompt(id, raw) {
  const text = stripAnsi(raw);
  if (id === 'claude') {
    const matches = text.match(CLAUDE_URL_RE) ?? [];
    const manual = matches.find((u) => u.includes('platform.claude.com'));
    return { url: manual };
  }
  if (id === 'github') {
    const code =
      /one-time code:\s*([A-Z0-9]{4}-[A-Z0-9]{4,7})/i.exec(text)?.[1] ??
      CODE_RE.exec(text)?.[0];
    return { url: 'https://github.com/login/device', code };
  }
  return { url: 'https://auth.openai.com/codex/device', code: CODE_RE.exec(text)?.[0] };
}
// ── end copy ──

const cases = [
  ['codex', 'codex_raw.txt'],
  ['github', 'gh_raw.txt'],
  ['claude', 'claude_raw.txt'],
];

for (const [id, file] of cases) {
  const raw = readFileSync(new URL(file, import.meta.url), 'utf8');
  const out = parseLoginPrompt(id, raw);
  console.log(`\n=== ${id} ===`);
  console.log('url :', out.url);
  console.log('code:', out.code ?? '(none)');
  // sanity assertions
  if (id === 'codex' && !/^[A-Z0-9]{4}-[A-Z0-9]{4,7}$/.test(out.code ?? '')) console.log('!! codex code missing');
  if (id === 'github' && !/^[A-Z0-9]{4}-[A-Z0-9]{4,7}$/.test(out.code ?? '')) console.log('!! github code missing');
  if (id === 'claude') {
    if (!out.url) console.log('!! claude url missing');
    else if (!out.url.includes('platform.claude.com')) console.log('!! claude url is not the manual one');
    else if (/[\\✢·✶✻✽*]/.test(out.url)) console.log('!! claude url has spinner junk:', out.url.slice(-8));
  }
}

