78	 * Check which providers are already authenticated on a sprite. Runs a single
79	 * cheap shell command that inspects each provider's on-disk credentials. Never
80	 * throws — returns all-false if the sprite can't be reached.
81	 */
82	export async function checkAccounts(spriteName: string): Promise<AccountStatus> {
83	  // Codex writes ~/.codex/auth.json; gh writes ~/.config/gh/hosts.yml; Claude
84	  // writes ~/.claude/.credentials.json (or we store a token in ~/.sprite_env).
85	  const command = [
86	    'c=0; [ -s "$HOME/.codex/auth.json" ] && c=1',
87	    'g=0; { grep -qs oauth_token "$HOME/.config/gh/hosts.yml" || [ -s "$HOME/.git-credentials" ]; } && g=1',
88	    'l=0; { [ -s "$HOME/.claude/.credentials.json" ] || grep -qs CLAUDE_CODE_OAUTH_TOKEN "$HOME/.sprite_env"; } && l=1',
89	    'echo "codex=$c github=$g claude=$l"',
90	  ].join('; ');
91	
92	  const { output, success } = await runExec(spriteName, command, 20);
93	  if (!success && !output.includes('codex=')) return { ...EMPTY_STATUS };
94	
95	  const read = (key: ProviderId) => new RegExp(`${key}=([01])`).exec(output)?.[1] === '1';
96	  return { codex: read('codex'), github: read('github'), claude: read('claude') };
97	}
98	
